.container {
  float: left;
  width: 100%;
}
@supports (display: flex) {
  .container {
    display: flex;
  }
}

.container {
  display: table;
  width: 90%;
}
@supports (display: grid) {
  .container {
    display: grid;
    grid-gap: 10px;
  }
}

@supports not (display: grid) {
  .warning {
    background-color: pink;
    border: 1px solid red;
  }
}
